using System.IO;using UnityEngine;using UnityEditor;
public static class ExportCampusTree {public static string Run(){var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ThirdParty/SchoolExpansion/tree_small_02/tree_small_02.fbx");var mf=p.GetComponentInChildren<MeshFilter>();var m=mf.sharedMesh;var path="../SourceAssets/CampusExterior/tree-source.bin";using(var w=new BinaryWriter(File.Create(path))){w.Write(m.vertexCount);w.Write(m.subMeshCount);var v=m.vertices;var uv=m.uv;var n=m.normals;for(int i=0;i<v.Length;i++){var point=mf.transform.TransformPoint(v[i]);w.Write(point.x);w.Write(point.y);w.Write(point.z);w.Write(uv[i].x);w.Write(uv[i].y);var norm=mf.transform.TransformDirection(n[i]);w.Write(norm.x);w.Write(norm.y);w.Write(norm.z);}for(int s=0;s<m.subMeshCount;s++){var ids=m.GetTriangles(s);w.Write(ids.Length);foreach(int i in ids)w.Write(i);}}return path;}}
